// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { FieldProps } from "./field.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Field";

// Generate child element class names for the component, should match available style slots
export const FieldClasses = {
  root: "exp-textura_field",
  main: "exp-textura_field_main",
  sm: "exp-textura_field_sm",
  controlPlacementInline: "exp-textura_field_control_placement_inline",
  controlPlacementInlineTrailing: "exp-textura_field_control_placement_inline_trailing",
  label: "exp-textura_field_label",
  labelDisabled: "exp-textura_field_label-disabled",
  requiredIndicator: "exp-textura_field_required_indicator",
  controlContainer: "exp-textura_field_control_container",
  error: "exp-textura_field_error",
  errorIcon: "exp-textura_field_error_icon",
  helpText: "exp-textura_field_help_text",
  helpTextTooltipTrigger: "exp-textura_field_help_text_tooltip_trigger",
  helpTextPopoverTrigger: "exp-textura_field_help_text_popover_trigger",
  subtext: "exp-textura_field_subtext",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: FieldProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<FieldProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[8]),
    width: "100%",

    [`.${FieldClasses.label}`]: {
      ...theme.typography.body.mdAccent,
      color: theme.color.content.strong,
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.label,
    },

    [`.${FieldClasses.labelDisabled}`]: {
      color: theme.color.content.disabled,
      ...styleSlots?.labelDisabled,
    },

    [`.${FieldClasses.controlContainer}`]: {
      display: "flex",
      ...theme.typography.body.md,
      color: theme.color.content.default,
      ...styleSlots?.controlContainer,
    },

    [`.${FieldClasses.main}`]: {
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.main,

      [`&.${FieldClasses.controlPlacementInline}`]: {
        flexDirection: "row",
        alignItems: "center",
      },

      [`&.${FieldClasses.controlPlacementInlineTrailing}`]: {
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",

        [`.${FieldClasses.label}`]: {
          flex: 1,
        },
      },
    },

    [`.${FieldClasses.requiredIndicator}`]: {
      marginInlineStart: `calc(${theme.toRem(theme.spacing[8])} * -1)`,
      color: theme.color.content.utility.critical,
      ...styleSlots?.requiredIndicator,
    },

    [`.${FieldClasses.helpTextTooltipTrigger}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.utility.info,
      fontSize: theme.toRem(12),
    },

    [`.${FieldClasses.helpTextPopoverTrigger}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.utility.info,
      fontSize: theme.toRem(12),
    },

    [`.${FieldClasses.helpText}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.weak,
      ...styleSlots?.helpText,
    },

    [`.${FieldClasses.subtext}`]: {
      ...theme.typography.body.mdAccent,
      color: theme.color.content.weak,
      ...styleSlots?.subtext,
    },

    [`.${FieldClasses.error}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.utility.critical,
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.error,
    },

    [`&.${FieldClasses.sm}`]: {
      gap: theme.toRem(theme.spacing[4]),
      [`.${FieldClasses.main}`]: {
        gap: theme.toRem(theme.spacing[4]),
      },
      [`.${FieldClasses.label}`]: {
        ...theme.typography.body.smAccent,
      },
      [`.${FieldClasses.controlContainer}`]: {
        ...theme.typography.body.sm,
      },
      [`.${FieldClasses.helpText}`]: {
        ...theme.typography.body.sm,
      },
      [`.${FieldClasses.subtext}`]: {
        ...theme.typography.body.smAccent,
      },
      [`.${FieldClasses.error}`]: {
        ...theme.typography.body.sm,
      },
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("formSize", "isInvalid");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledField = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<FieldProps>((props) => generateStyles(props));
